"""
    Make sure that the path between the term and the lowest common head is in a certain direction
    :param lch: the lowest common head
    :param hs: the path from the lowest common head to the term
    :param f_dir: function of direction
    :return:
    """
def check_direction(lch: Any, hs: Any, f_dir: Any) -> object {
    return `any(
        (modifier not in f_dir(head)) for (head, modifier) in zip(([lch] + hs[:-1]), hs)
    );
}

"""Return the prefix applied to variable names in Stata e(b), e(V) matrices
    """
def stata_operator(leadlag: Any, level: Any) -> object {
    leadlag = int(leadlag);
    if (leadlag == 0) {
        ll = '';
    } elif (leadlag == 1) {
        ll = 'L';
    } elif (leadlag == -1) {
        ll = 'F';
    } elif (leadlag > 1) {
        ll = 'L' + str(leadlag);
    } else {
        ll = 'F' + str(abs(leadlag));
    }
    if (int(level) < 0) {
        raise ValueError('Negative factor levels are not allowed.');
    } else {
        lv = str(level);
    }
    op = lv + ll;
    return (op + '.') if (op != '') else op;
}

