"""
    Parses the zone conditions definition YAML files to find the condition
    that match both the zone condition passed in.
    """
def getConditionInZoneConditions(
    zone_condition: Any, zone_conditions_data: Any
) -> object {
    condition = {};
    for c in zone_conditions_data['conditions'] {
        if (zone_condition != c['name']) {
            continue;
        }
        condition['type'] = c['type'];
        properties = [];
        for p in c['properties'] {
            property = {};
            property['property'] = p['property'];
            property['interface'] = p['interface'];
            property['path'] = p['path'];
            property['type'] = p['type'].lower();
            property['value'] = str(p['value']).lower();
            properties.append(property);
        }
        condition['properties'] = properties;
        return condition;
    }
}

"""set a bit in a bitstring, 0 = MSB"""
def set_bitstring_bit(bitstring: Any, bitnum: Any, valuetoset: Any) -> object {
    bytepos = bitnum >> 3;
    bitpos = 7 - (bitnum % 8);
    bytevalue = bitstring[bytepos];
    if valuetoset {
        if (bytevalue & (2 ** bitpos)) {
            return bitstring;
        } else {
            return (
                bitstring[:bytepos]
                + (bytevalue + (2 ** bitpos)).to_bytes(1, byteorder='big')
                + bitstring[(bytepos + 1):]
            );
        }
    } elif (bytevalue & (2 ** bitpos)) {
        return (
            bitstring[:bytepos]
            + (bytevalue - (2 ** bitpos)).to_bytes(1, byteorder='big')
            + bitstring[(bytepos + 1):]
        );
    } else {
        return bitstring;
    }
}

